public static void main(String[] args) throws Exception {
    java.util.Scanner sc = new java.util.Scanner(System.in);
    java.io.PrintWriter pw = new java.io.PrintWriter(System.out);

    long N = sc.nextLong();
    long M = sc.nextLong();
    long K = sc.nextLong();

    long LCM = N / gcd(N, M) * M;
    long l = 1, r = K * Math.max(N, M);

    while (l < r) {
        long mid = (l + r) / 2;
        long count = (mid / N) + (mid / M) - 2 * (mid / LCM);

        if (count >= K) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }

    pw.print(l);
    pw.flush();
    sc.close();
    pw.close();
}

private static long gcd(long a, long b) {
    while (b != 0) {
        long t = b;
        b = a % b;
        a = t;
    }
    return a;
}
